'use strict';
const $=id=>document.getElementById(id),C=window.CallTime;
let parsed=null,event=null,format='12',destination='Europe/Belgrade';
try{const saved=localStorage.getItem('call-time-destination');if(saved){new Intl.DateTimeFormat('en',{timeZone:saved});destination=saved;}}catch{}
try{format=localStorage.getItem('call-time-format')==='24'?'24':'12';}catch{}
document.querySelector('input[name="format"][value="'+format+'"]').checked=true;
const today=new Intl.DateTimeFormat('en-CA',{timeZone:destination,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
$('call-date').value=today;
function showError(msg){$('error').textContent=msg;$('error').hidden=!msg;}
function reset(){event=null;$('result').hidden=true;$('empty-result').hidden=false;$('calendar-status').textContent='';showError('');}
function t(ms,zone=destination){return new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',hour12:format==='12'}).format(new Date(ms));}
function day(ms,zone=destination){return new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date(ms));}
function plain(minutes){return t(Date.UTC(2026,0,1,0,minutes),'UTC');}
function options(items){$('zone-choice').replaceChildren();for(const [value,label] of items){const el=document.createElement('option');el.value=value;el.textContent=label;$('zone-choice').append(el);}}
function zones(){if(!parsed)return;let choices=parsed.choices,note='Multiple timezones use this abbreviation.';if(!parsed.zone){choices=Object.entries(C.regions).map(([city,zone])=>[zone,city]);note='Choose a city or paste a GMT offset.';}
if(!choices&&parsed.standardRegion&&C.validDate($('call-date').value)){const off=C.offset(Date.parse($('call-date').value+'T12:00Z'),parsed.standardRegion);if(off!==Number(parsed.zone.slice(6))){choices=[[parsed.zone,parsed.label+' literally · UTC '+offsetText(Number(parsed.zone.slice(6)))],[parsed.standardRegion,'Local time in '+parsed.standardRegion.split('/').pop().replaceAll('_',' ')+' (daylight saving)']];note=parsed.label+' or local summer time? Confirm with the recruiter.';}}
$('zone-wrap').hidden=!choices;options(choices?[['','Choose to confirm…'],...choices]:[]);$('zone-note').textContent=note;}
function offsetText(n){return (n<0?'−':'+')+String(Math.floor(Math.abs(n)/60)).padStart(2,'0')+':'+String(Math.abs(n)%60).padStart(2,'0');}
function dateNote(){let note='';if(parsed?.missingYear)note='Year missing — confirm the date.';if(parsed?.weekday&&C.validDate($('call-date').value)){let w=new Intl.DateTimeFormat('en-US',{weekday:'long',timeZone:'UTC'}).format(new Date($('call-date').value+'T12:00Z'));if(w.toLowerCase()!==parsed.weekday.toLowerCase())note='The message says '+parsed.weekday+', but this date is '+w+'. Confirm the correct date with your recruiter.';}if(parsed?.end!==null&&parsed?.end<=parsed?.start)note+=' The end is on the following day.';$('date-note').textContent=note;$('date-note').hidden=!note;}
function updatePhrase(){reset();try{parsed=C.parse($('phrase').value,Number(today.slice(0,4)));if(parsed.date)$('call-date').value=parsed.date;$('parsed').textContent=plain(parsed.start)+(parsed.end!==null?' – '+plain(parsed.end):'')+' · '+(parsed.label||'Choose a timezone below');$('duration-wrap').hidden=parsed.end!==null;zones();dateNote();}catch(e){parsed=null;$('parsed').textContent='';$('zone-wrap').hidden=true;showError(e.message);}}
function render(){if(!event||!resolveDestination($('destination').value))return;$('empty-result').hidden=true;$('result').hidden=false;$('result-date').textContent=day(event.start);$('result-time').replaceChildren();const str=t(event.start),m=str.match(/^(.*)\s(AM|PM)$/);if(m){$('result-time').append(document.createTextNode(m[1]));const sm=document.createElement('small');sm.textContent=m[2];$('result-time').append(sm);}else $('result-time').textContent=str;
const sameDay=day(event.start)===day(event.end);$('result-end').textContent='to '+t(event.end)+(sameDay?'':' · '+day(event.end))+' · '+Math.round((event.end-event.start)/60000)+' min';const delta=event.localOffset-event.sourceOffset;const hours=Math.floor(Math.abs(delta)/60),mins=Math.abs(delta)%60;const shift=hours+'h'+(mins?' '+mins+'m':'');$('difference').textContent=delta===0?'No time difference':shift+(delta>0?' ahead of':' behind')+' their time';let sourceLabel=$('zone-wrap').hidden?parsed.label:$('zone-choice').selectedOptions[0].textContent;$('source-readback').textContent=plain(parsed.start)+(parsed.end!==null?' – '+plain(parsed.end):'')+' · '+sourceLabel+' · '+event.sourceDate;$('local-zone').textContent='UTC '+offsetText(event.localOffset);}
function submit(){reset();if(!resolveDestination($('destination').value))throw Error('Choose your city or timezone.');if(!parsed)throw Error('Check the message above before converting.');const zone=$('zone-wrap').hidden?parsed.zone:$('zone-choice').value;if(!zone)throw Error('Choose which timezone the recruiter meant.');event=C.convert(parsed,$('call-date').value,zone,Number($('duration').value),destination);render();return {start:new Date(event.start).toISOString(),end:new Date(event.end).toISOString(),localTime:t(event.start),localDate:day(event.start),destination};}
$('converter').addEventListener('submit',e=>{e.preventDefault();try{submit();if(window.matchMedia("(max-width:740px)").matches)$("result-heading").scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion:reduce)").matches?"instant":"smooth",block:"start"});}catch(err){showError(err.message);}});
$('phrase').addEventListener('input',updatePhrase);
$('call-date').addEventListener('input',()=>{reset();zones();dateNote();});
$('zone-choice').addEventListener('change',reset);$('duration').addEventListener('change',reset);
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('phrase').value=b.dataset.example;updatePhrase();}));
document.querySelectorAll('input[name="format"]').forEach(r=>r.addEventListener('change',()=>{format=r.value;try{localStorage.setItem('call-time-format',format);}catch{}if(parsed)$('parsed').textContent=plain(parsed.start)+(parsed.end!==null?' – '+plain(parsed.end):'')+' · '+(parsed.label||'Choose a timezone below');render();}));
$('calendar').addEventListener('click',()=>{if(!event)return;const blob=new Blob([C.ics(event)],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='recruiter-call.ics';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);$('calendar-status').textContent='Open the downloaded file and confirm Add in Calendar.';});

const destinationOptions=new Map();
function zoneLabel(zone){return zone==='UTC'?'UTC':zone.split('/').slice(1).join(' / ').replaceAll('_',' ')+' · '+zone;}
let allZones=[];try{allZones=Intl.supportedValuesOf('timeZone');}catch{allZones=Object.values(C.regions);}
for(const zone of new Set([...allZones,...Object.values(C.regions),'UTC']))destinationOptions.set(zoneLabel(zone),zone);
for(const [city,zone] of Object.entries(C.regions))destinationOptions.set(city+' · '+zone,zone);
for(const [label,zone] of [...destinationOptions].sort((a,b)=>a[0].localeCompare(b[0]))){const option=document.createElement('option');option.value=label;$('destinations').append(option);}
$('destination').value=zoneLabel(destination);$('local-zone').textContent=destination;
function resolveDestination(value){const v=value.trim();const found=[...destinationOptions].find(([label,zone])=>label.toLowerCase()===v.toLowerCase()||zone.toLowerCase()===v.toLowerCase());if(found)return found[1];const city=Object.keys(C.regions).find(c=>c.toLowerCase()===v.toLowerCase());if(city)return C.regions[city];if(v.includes('/')||v.toUpperCase()==='UTC'){try{return new Intl.DateTimeFormat('en',{timeZone:v}).resolvedOptions().timeZone;}catch{}}return null;}
$('destination').addEventListener('input',()=>{const zone=resolveDestination($('destination').value);$('destination-note').hidden=!!zone;$('destination').setAttribute('aria-invalid',String(!zone));if(!zone){$('result').hidden=true;$('empty-result').hidden=false;return;}destination=zone;try{localStorage.setItem('call-time-destination',destination);}catch{}$('local-zone').textContent=destination;if(event){event.destination=destination;event.localOffset=C.offset(event.start,destination);render();}});

updatePhrase();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'stage_call_conversion',description:'Fill the recruiter message and optional source date. Leaves confirmation and conversion to the user.',inputSchema:{type:'object',properties:{message:{type:'string'},date:{type:'string',description:'Source date in YYYY-MM-DD format'}},required:['message'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.message!=='string'||input.message.length>10000)throw Error('Provide a message under 10,000 characters.');if(input.date!==undefined&&!C.validDate(input.date))throw Error('Provide a valid YYYY-MM-DD date.');C.parse(input.message,Number(today.slice(0,4)));$('phrase').value=input.message;updatePhrase();if(input.date){$('call-date').value=input.date;zones();dateNote();}return {status:'awaiting_confirmation',date:$('call-date').value,interpretation:$('parsed').textContent,timezoneChoiceRequired:!$('zone-wrap').hidden};}})).catch(()=>{});}catch{}}

// Tooltips also open on touch and close with Escape.
document.querySelectorAll(".help").forEach(el=>{el.addEventListener("click",e=>{e.preventDefault();el.classList.toggle("open");});el.addEventListener("keydown",e=>{if(e.key==="Escape"){el.classList.remove("open");el.blur();}if(e.key==="Enter"||e.key===" "){e.preventDefault();el.classList.toggle("open");}});});
